



SELECT 
    u.user_id, 
    'disponible' AS status, 
    CURRENT_TIMESTAMP AS changed_at
FROM users u
WHERE NOT EXISTS (
    SELECT 1 
    FROM user_availability ua 
    WHERE ua.user_id = u.user_id
);

    
